// ---------- Bottom nav component ----------
async function nav(active){
  const f=figma.createFrame();f.name='BottomNav';f.resize(414,74);f.fills=S(C.white);
  f.layoutMode='HORIZONTAL';f.paddingTop=12;f.paddingBottom=14;f.itemSpacing=0;f.counterAxisAlignItems='CENTER';
  f.strokes=S(C.line);f.strokeAlign='INSIDE';f.strokeTopWeight=1;f.strokeBottomWeight=0;f.strokeLeftWeight=0;f.strokeRightWeight=0;
  const items=[['Home','6:269'],['Product','6:270'],['Transaction','6:271'],['Account','6:272']];
  for(const [label,id] of items){
    const on=label===active;const col=on?C.p:C.t3;
    const it=figma.createFrame();it.name='tab_'+label;it.fills=[];it.layoutMode='VERTICAL';it.itemSpacing=5;
    it.counterAxisAlignItems='CENTER';it.primaryAxisAlignItems='CENTER';
    f.appendChild(it);it.layoutGrow=1;it.layoutAlign='STRETCH';
    const ic=await icon(id,22,col);it.appendChild(ic);
    const tl=txt(label,11,on?'Semi Bold':'Regular','Inter',col,14);tl.name='label';it.appendChild(tl);
  }
  const comp=figma.createComponent();comp.resize(414,74);comp.fills=[];
  comp.appendChild(f);f.x=0;f.y=0;
  comp.name='BottomNav/'+active;
  f.remove();
  return comp;
}
